 Object.assign(step('Navnet på omslaget','nora','Nora har lagt den blå boka ved siden av Hauglands stemplede kvittering. Den ene gir henne mandat til å styre. Den andre viser hvem som svarte for gamle feil. Du får én av dem.','Ha fire trente folk og virksomhet i to byer.',{trained:4,cities:2},[help('La Nora beholde mandatet; ta den blå boka','Hun skriver navnet ditt med blekk. Under står også hennes eget.',18000,{item:'blueBook',influence:6,flag:'bookEndingPartner'}),choice('receipt','Ta kvitteringen og stå selv for oppgjørene','Haugland nikker til kopien. Nora beholder originalene og ber deg lese før du signerer.',{cost:18000,contact:'haugland',relation:1,item:'signedReceipt',heat:-8,flag:'bookEndingAccountable'}),exploit('Selg kundelista og avslutt samarbeidet','Nora river ut den siste blanke siden. Den blir liggende der boka lå.',32000,{flag:'bookEndingSold',contact:'nora',loyalty:-6})]),{callbacks:[{flag:'payrollBuried',text:'Nora krever sluttavtalen gjort opp åpent før boka kan skifte hender. Det koster 8 000 kr ekstra.',cost:8000},{flag:'ledgerTrustRepaired',text:'Kunden du ga en ny avtale, har levert sitt første oppgjør. Nora lar den kvitteringen ligge øverst.'}]})
